import React from 'react';
import { Composition } from 'remotion';
import content from '../content.json';
// Generated by `npm run assets` (scripts/build-assets.mjs).
import manifest from '../public/manifest.json';
import { FPS, H, Lipstick, Props, timeline, W } from './Lipstick';

const defaultProps = { manifest, content } as unknown as Props;

export const Root: React.FC = () => (
  <Composition
    id="Lipstick"
    component={Lipstick}
    width={W}
    height={H}
    fps={FPS}
    durationInFrames={timeline(defaultProps.manifest).total}
    defaultProps={defaultProps}
    calculateMetadata={({ props }) => ({ durationInFrames: timeline((props as Props).manifest).total })}
  />
);
